corpus_block("test-facet-labels.R: labeller() dispatches labellers", {
  get_labels_matrix <- function(plot, ...) {
    data <- ggplot_build(plot)
    layout <- data@layout
  
    labels <- get_labels_info(layout$facet, layout, ...)
    labeller <- match.fun(layout$facet$params$labeller)
  
    # Create matrix of labels
    matrix <- lapply(labeller(labels), cbind)
    matrix <- do.call("cbind", matrix)
    matrix
  }
  get_labels_info <- function(facet, panel, ...) {
    UseMethod("get_labels_info")
  }
  get_labels_info.FacetGrid <- function(facet, layout, type) {
    if (type == "rows") {
      labels <- unique(layout$layout[names(facet$params$rows)])
      attr(labels, "type") <- "rows"
      attr(labels, "facet") <- "grid"
    } else {
      labels <- unique(layout$layout[names(facet$params$cols)])
      attr(labels, "type") <- "cols"
      attr(labels, "facet") <- "grid"
    }
    labels
  }
  get_labels_info.FacetWrap <- function(facet, layout) {
    labels <- layout$layout[names(facet$params$facets)]
    attr(labels, "facet") <- "wrap"
    if (!is.null(facet$params$switch) && facet$params$switch == "x") {
      attr(labels, "type") <- "rows"
    } else {
      attr(labels, "type") <- "cols"
    }
    labels
  }
  .plot("test-facet-labels.R: labeller() dispatches labellers #1", p <- ggplot(mtcars, aes(wt, mpg)) + geom_point())
  expected_cyl_both <- cbind(paste("cyl:", c(4, 6, 8)))
  expected_am_both <- cbind(paste("am:", 0:1))
  .plot("test-facet-labels.R: labeller() dispatches labellers #2", p1 <- p + facet_wrap(~cyl, labeller = labeller(.rows = label_both)))
  .plot("test-facet-labels.R: labeller() dispatches labellers #3", p2 <- p + facet_wrap(~cyl, labeller = labeller(.cols = label_both)))
  .plot("test-facet-labels.R: labeller() dispatches labellers #4", p3 <- p + facet_wrap(~cyl, labeller = labeller(
      .cols = label_both, .rows = label_both)))
  .plot("test-facet-labels.R: labeller() dispatches labellers #5", p4 <- p + facet_grid(am ~ cyl, labeller = labeller(
      .cols = label_both, .rows = label_both)))
  .plot("test-facet-labels.R: labeller() dispatches labellers #6", p5 <- p + facet_wrap(~cyl, labeller = labeller(
      .rows = label_both, cyl = label_value)))
  .plot("test-facet-labels.R: labeller() dispatches labellers #7", p6 <- p + facet_grid(am + cyl ~ ., labeller = labeller(
       am = label_both, cyl = label_both)))
  .plot("test-facet-labels.R: labeller() dispatches labellers #8", p7 <- p + facet_grid(am ~ cyl, labeller = labeller(.default = label_both)))
})

